[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>SnapFrame — Capture, Create &amp; Share What You Love</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <link href="https://cdn.jsdelivr.net/npm/remixicon@4.6.0/fonts/remixicon.css" rel="stylesheet">
  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --black: #000000;
      --purple: #7638FA;
      --orange: #FF7A00;
      --purple-light: #9B6FFC;
      --orange-light: #FFB366;
      --bg: #FAFAFA;
      --text: #1A1A1A;
      --text-secondary: #555555;
      --text-muted: #888888;
      --border: #E5E5E5;
      --card-bg: #FFFFFF;
      --radius: 16px;
      --radius-sm: 10px;
      --radius-pill: 999px;
      --font: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font);
      background: var(--bg);
      color: var(--text);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      overflow-x: hidden;
    }

    a { color: inherit; text-decoration: none; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }
    img { display: block; max-width: 100%; }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* ── HEADER ── */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(255,255,255,0.85);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-bottom: 1px solid var(--border);
    }
    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 64px;
    }
    .logo {
      font-size: 1.35rem;
      font-weight: 800;
      letter-spacing: -0.5px;
      background: linear-gradient(135deg, var(--purple), var(--orange));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }
    .nav-desktop {
      display: flex;
      align-items: center;
      gap: 32px;
    }
    .nav-desktop a {
      font-size: 0.9rem;
      font-weight: 600;
      color: var(--text-secondary);
      transition: color 0.2s;
    }
    .nav-desktop a:hover { color: var(--black); }
    .btn-login {
      font-size: 0.875rem;
      font-weight: 700;
      padding: 10px 24px;
      border-radius: var(--radius-pill);
      background: var(--black);
      color: #fff;
      transition: opacity 0.2s;
    }
    .btn-login:hover { opacity: 0.85; }
    .hamburger {
      display: none;
      width: 40px;
      height: 40px;
      align-items: center;
      justify-content: center;
      border-radius: 8px;
      font-size: 1.5rem;
      transition: background 0.2s;
    }
    .hamburger:hover { background: rgba(0,0,0,0.05); }
    .hamburger .ri-close-line { display: none; }
    .hamburger.active .ri-menu-line { display: none; }
    .hamburger.active .ri-close-line { display: inline; }

    .mobile-nav {
      display: none;
      position: fixed;
      top: 65px;
      left: 0;
      right: 0;
      bottom: 0;
      z-index: 99;
      background: rgba(255,255,255,0.97);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      padding: 32px 24px;
      flex-direction: column;
      gap: 8px;
      opacity: 0;
      transform: translateY(-8px);
      transition: opacity 0.25s ease, transform 0.25s ease;
    }
    .mobile-nav.open {
      display: flex;
      opacity: 1;
      transform: translateY(0);
    }
    .mobile-nav a {
      font-size: 1.1rem;
      font-weight: 600;
      padding: 14px 16px;
      border-radius: var(--radius-sm);
      color: var(--text);
      transition: background 0.15s;
    }
    .mobile-nav a:hover { background: rgba(118,56,250,0.06); }
    .mobile-nav .btn-login-mobile {
      margin-top: 16px;
      text-align: center;
      font-size: 1rem;
      font-weight: 700;
      padding: 14px;
      border-radius: var(--radius-pill);
      background: var(--black);
      color: #fff;
    }

    /* ── HERO ── */
    .hero {
      position: relative;
      min-height: 580px;
      display: flex;
      align-items: center;
      overflow: hidden;
    }
    .hero::before {
      content: '';
      position: absolute;
      inset: 0;
      background:
        radial-gradient(ellipse 80% 60% at 20% 50%, rgba(118,56,250,0.12) 0%, transparent 60%),
        radial-gradient(ellipse 60% 50% at 80% 40%, rgba(255,122,0,0.10) 0%, transparent 60%);
      pointer-events: none;
    }
    .hero-inner {
      position: relative;
      z-index: 1;
      max-width: 720px;
      padding: 80px 0 60px;
    }
    .hero h1 {
      font-size: clamp(2.4rem, 5.5vw, 3.75rem);
      font-weight: 800;
      line-height: 1.1;
      letter-spacing: -1.5px;
      margin-bottom: 20px;
    }
    .hero h1 span {
      background: linear-gradient(135deg, var(--purple), var(--orange));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }
    .hero p {
      font-size: 1.15rem;
      color: var(--text-secondary);
      max-width: 520px;
      margin-bottom: 36px;
      line-height: 1.65;
    }
    .btn-cta {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-size: 1rem;
      font-weight: 700;
      padding: 16px 36px;
      border-radius: var(--radius-pill);
      background: linear-gradient(135deg, var(--purple), var(--purple-light));
      color: #fff;
      box-shadow: 0 4px 24px rgba(118,56,250,0.3);
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .btn-cta:hover {
      transform: translateY(-2px);
      box-shadow: 0 6px 32px rgba(118,56,250,0.4);
    }
    .hero-visual {
      position: absolute;
      right: -40px;
      top: 50%;
      transform: translateY(-50%);
      width: 420px;
      height: 420px;
      border-radius: 50%;
      background: linear-gradient(135deg, rgba(118,56,250,0.08), rgba(255,122,0,0.08));
      display: flex;
      align-items: center;
      justify-content: center;
      pointer-events: none;
    }
    .hero-visual-inner {
      width: 320px;
      height: 320px;
      border-radius: 50%;
      background: linear-gradient(135deg, rgba(118,56,250,0.12), rgba(255,122,0,0.10));
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .hero-visual i {
      font-size: 6rem;
      background: linear-gradient(135deg, var(--purple), var(--orange));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    /* ── SECTION SHARED ── */
    .section { padding: 80px 0; }
    .section-label {
      font-size: 0.75rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 2px;
      color: var(--purple);
      margin-bottom: 12px;
    }
    .section-heading {
      font-size: clamp(1.75rem, 3.5vw, 2.5rem);
      font-weight: 800;
      line-height: 1.2;
      letter-spacing: -0.5px;
      max-width: 680px;
      margin-bottom: 16px;
    }
    .section-desc {
      font-size: 1.05rem;
      color: var(--text-secondary);
      max-width: 560px;
      line-height: 1.7;
      margin-bottom: 28px;
    }
    .section-link {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 1rem;
      font-weight: 700;
      color: var(--purple);
      transition: gap 0.2s;
    }
    .section-link:hover { gap: 10px; }

    /* ── FEATURES ── */
    .features {
      background: var(--card-bg);
      border-top: 1px solid var(--border);
      border-bottom: 1px solid var(--border);
    }
    .features-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
      margin-top: 40px;
    }
    .feature-card {
      padding: 28px 24px;
      border-radius: var(--radius);
      background: var(--bg);
      border: 1px solid var(--border);
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .feature-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 8px 32px rgba(0,0,0,0.06);
    }
    .feature-icon {
      width: 48px;
      height: 48px;
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.4rem;
      margin-bottom: 16px;
      color: #fff;
    }
    .feature-icon.clips { background: linear-gradient(135deg, var(--purple), var(--purple-light)); }
    .feature-icon.stories { background: linear-gradient(135deg, var(--orange), var(--orange-light)); }
    .feature-icon.dms { background: linear-gradient(135deg, #00C9A7, #00E6BD); }
    .feature-icon.explore { background: linear-gradient(135deg, #FF4081, #FF80AB); }
    .feature-card h3 {
      font-size: 1.05rem;
      font-weight: 700;
      margin-bottom: 6px;
    }
    .feature-card p {
      font-size: 0.88rem;
      color: var(--text-secondary);
      line-height: 1.55;
    }

    /* ── SAFETY ── */
    .safety {
      background: linear-gradient(180deg, #F5F0FF 0%, var(--bg) 100%);
    }
    .safety-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 48px;
      align-items: center;
    }
    .safety-visual {
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .safety-visual-card {
      width: 100%;
      max-width: 400px;
      aspect-ratio: 4/3;
      border-radius: var(--radius);
      background: linear-gradient(135deg, rgba(118,56,250,0.06), rgba(118,56,250,0.02));
      border: 1px solid rgba(118,56,250,0.12);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 16px;
      padding: 32px;
    }
    .safety-visual-card i {
      font-size: 3.5rem;
      color: var(--purple);
    }
    .safety-visual-card span {
      font-size: 1.1rem;
      font-weight: 700;
      color: var(--purple);
    }
    .safety-badges {
      display: flex;
      gap: 10px;
      margin-top: 20px;
    }
    .safety-badge {
      padding: 8px 16px;
      border-radius: var(--radius-pill);
      background: rgba(118,56,250,0.08);
      color: var(--purple);
      font-size: 0.78rem;
      font-weight: 600;
    }

    /* ── CREATORS ── */
    .creators {
      background: var(--card-bg);
      border-top: 1px solid var(--border);
      border-bottom: 1px solid var(--border);
    }
    .creators-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 48px;
      align-items: center;
    }
    .creators-visual {
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .creators-visual-card {
      width: 100%;
      max-width: 400px;
      aspect-ratio: 4/3;
      border-radius: var(--radius);
      background: linear-gradient(135deg, rgba(255,122,0,0.08), rgba(255,122,0,0.02));
      border: 1px solid rgba(255,122,0,0.15);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 16px;
      padding: 32px;
    }
    .creators-visual-card i {
      font-size: 3.5rem;
      color: var(--orange);
    }
    .creators-visual-card span {
      font-size: 1.1rem;
      font-weight: 700;
      color: var(--orange);
    }
    .creators-stats {
      display: flex;
      gap: 24px;
      margin-top: 20px;
    }
    .creator-stat {
      text-align: center;
    }
    .creator-stat strong {
      display: block;
      font-size: 1.5rem;
      font-weight: 800;
      background: linear-gradient(135deg, var(--orange), var(--orange-light));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }
    .creator-stat span {
      font-size: 0.78rem;
      color: var(--text-muted);
      font-weight: 500;
    }

    /* ── TAGLINE BANNER ── */
    .tagline-banner {
      padding: 80px 0;
      text-align: center;
      position: relative;
      overflow: hidden;
    }
    .tagline-banner::before {
      content: '';
      position: absolute;
      inset: 0;
      background:
        radial-gradient(ellipse 70% 60% at 30% 50%, rgba(118,56,250,0.06) 0%, transparent 60%),
        radial-gradient(ellipse 50% 50% at 70% 50%, rgba(255,122,0,0.05) 0%, transparent 60%);
      pointer-events: none;
    }
    .tagline-banner h2 {
      position: relative;
      font-size: clamp(1.8rem, 4vw, 3rem);
      font-weight: 800;
      line-height: 1.2;
      letter-spacing: -1px;
    }
    .tagline-banner h2 span {
      background: linear-gradient(135deg, var(--purple), var(--orange));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    /* ── NEWS ── */
    .news { padding: 80px 0; }
    .news-header {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      margin-bottom: 36px;
    }
    .news-header .section-link { margin-bottom: 4px; }
    .carousel-wrapper {
      position: relative;
    }
    .carousel-track {
      display: flex;
      gap: 20px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none;
      padding: 4px 0 16px;
    }
    .carousel-track::-webkit-scrollbar { display: none; }
    .news-card {
      flex: 0 0 300px;
      scroll-snap-align: start;
      border-radius: var(--radius);
      background: var(--card-bg);
      border: 1px solid var(--border);
      overflow: hidden;
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .news-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 8px 32px rgba(0,0,0,0.08);
    }
    .news-thumb {
      width: 100%;
      aspect-ratio: 16/9;
      background: linear-gradient(135deg, rgba(118,56,250,0.08), rgba(255,122,0,0.06));
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
    }
    .news-thumb i {
      font-size: 2.5rem;
      color: var(--purple);
      opacity: 0.4;
    }
    .news-thumb-1 { background: linear-gradient(135deg, rgba(118,56,250,0.12), rgba(155,111,252,0.08)); }
    .news-thumb-2 { background: linear-gradient(135deg, rgba(255,122,0,0.12), rgba(255,179,102,0.08)); }
    .news-thumb-3 { background: linear-gradient(135deg, rgba(0,201,167,0.12), rgba(0,230,189,0.08)); }
    .news-thumb-3 i { color: #00C9A7; }
    .news-thumb-4 { background: linear-gradient(135deg, rgba(255,64,129,0.12), rgba(255,128,171,0.08)); }
